93	const PATH = [[1255, 652], [1240, 780], [560, 770], [640, 1060]];
94	function pathCenter(t) {
95	  const u = 1 - t, c = [u * u * u, 3 * u * u * t, 3 * u * t * t, t * t * t];
96	  const at = i => c.reduce((s, v, j) => s + v * PATH[j][i], 0);
97	  return [at(0), at(1)];
98	}
99	function pathNormal(t) {
100	  const [ax, ay] = pathCenter(Math.max(0, t - 0.01)), [bx, by] = pathCenter(Math.min(1, t + 0.01)), len = Math.hypot(bx - ax, by - ay);
101	  return [-(by - ay) / len, (bx - ax) / len];
102	}
103	const halfWidth = t => 26 + 189 * t ** 1.6;
104	function pathOutline() {
105	  const side = sign => Array.from({length: 41}, (_, i) => {
106	    const t = i / 40, [x, y] = pathCenter(t), [nx, ny] = pathNormal(t), hw = halfWidth(t) * sign;
107	    return [x + nx * hw, Math.min(1056, y + ny * hw)];
108	  });
109	  return [...side(1), ...side(-1).reverse()];
110	}
