17	  let sum = 0, sq = 0, purple = 0, opaque = true, count = 0, hash = 2166136261;
18	  for (let i = 0; i < data.length; i += 4 * 61) {
19	    const [r, g, b, a] = [data[i], data[i + 1], data[i + 2], data[i + 3]];
20	    const luma = 0.2126 * r + 0.7152 * g + 0.0722 * b;
21	    sum += luma; sq += luma * luma; count += 1;
22	    if (a !== 255) opaque = false;
