  if (beat !== `#${beats.get(t)}`) errors.push(`${name}: 拍号 ${beat} 与节拍表 ${beats.get(t)} 不符`);
  if (!['实物遮挡', '撕开', '同场延续'].includes(kind)) errors.push(`${name}: 类型 ${kind}`);
  count[kind] = (count[kind] ?? 0) + 1;
  if (BANNED.test(how + seam)) errors.push(`${name}: 使用禁止手法`);
  const bodyLen = how.length + seam.length;
  if (bodyLen < 40) errors.push(`${name}: 内容过短`);

  // 相接帧：「相接 我 (…)」是这一帧的方框，必须等于上一镜的最终状态。
  const seamPart = seam.split('；')[0];
  const boxes = [...seamPart.matchAll(BOX)];
  const hiddenOk = /不入画|遮挡期间|未入画/.test(seam);
  if (!boxes.length && !hiddenOk) errors.push(`${name}: 没有相接帧方框，也没有说明角色不入画`);
  for (const m of boxes) {
    const role = ROLE[m[1]], box = {x: +m[2], y: +m[3], u: +m[4]};
    const want = SEAM_OVERRIDE[pair]?.[role] ?? posterOf(a.id, role);
    if (!want) errors.push(`${name}: ${a.id} 没有 ${m[1]}`);
    else if (!close(box, want)) errors.push(`${name}: ${m[1]} 相接帧 ${JSON.stringify(box)} ≠ ${a.id} ${JSON.stringify(want)}`);
  }
  // 「到 我 (…)」是这个方框最终移到的位置，必须等于下一镜关键画面。
  for (const m of seam.matchAll(/到 (我|新娘|新郎) \((-?[\d.]+), (-?[\d.]+), ([\d.]+)\)/g)) {
    const role = ROLE[m[1]], box = {x: +m[2], y: +m[3], u: +m[4]}, want = posterOf(b.id, role);
    if (!want) errors.push(`${name}: ${b.id} 没有 ${m[1]}`);
    else if (!close(box, want)) errors.push(`${name}: ${m[1]} 去向 ${JSON.stringify(box)} ≠ ${b.id} ${JSON.stringify(want)}`);
  }
  // 两镜都有的角色必须写明去向，除非遮挡前后不是同一时空。
  for (const role of ['me', 'bride', 'groom']) {
    if (ANCHOR[a.id][role] && ANCHOR[b.id][role] && kind === '同场延续' && !boxes.some(m => ROLE[m[1]] === role)) errors.push(`${name}: 同场延续缺少 ${role} 的相接方框`);
  }
  const frame = frames[i + 1];
  const field = frame.match(/^- transition_in: (.*)$/m)?.[1] ?? '';
  if (!field.startsWith(`${tag} ${kind}`)) errors.push(`${name}: transition_in 未指向衔接表：${field}`);
  if (BANNED.test(field)) errors.push(`${name}: transition_in 使用禁止手法`);
  if (kind !== '同场延续') {
    const lo = Number(frame.match(/^- reads: .*?（(\d+(?:\.\d+)?)-/m)?.[1]);
    if (lo < 0.8) errors.push(`${name}: reads 从 ${lo} 秒开始，早于揭开完成`);
  }
});
for (const body of frames) if (BANNED.test(body.match(/^- camera: (.*)$/m)?.[1] ?? '')) errors.push(`camera 使用禁止手法：${body.slice(0, 12)}`);

if (errors.length) { console.log(JSON.stringify({status: 'failed', count: errors.length, errors}, null, 1)); process.exit(1); }
console.log(JSON.stringify({status: 'passed', rows: rows.length, kinds: count}));
